import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>PNG هي صيغة الشعارات والأيقونات ولقطات الشاشة، لكنها أيضًا صيغة ثقيلة. شعار PNG قد يزن مئات الكيلوبايتات.</p>\n<p>تحويل PNG إلى WebP يحافظ على الشفافية التي تجعل PNG مفيدًا، وفي الوقت نفسه يصغّر الملف بشكل كبير.</p>\n<p>يشرح هذا الدليل كيف يعمل التحويل، وما الإعدادات التي تستخدمها، ومتى يكون WebP هو الوجهة الصحيحة.</p>\n<h2 id=\"what-is-png-to-webp\">ما تحويل PNG إلى WebP؟</h2>\n<p>ما تحويل PNG إلى WebP؟ إعادة ترميز صورة PNG بصيغة WebP مع الحفاظ على الشفافية. النتيجة ملف أصغر بالصورة نفسها تقريبًا.</p>\n<p>التحويل يحافظ على قناة ألفا، لذلك تبقى المناطق الشفافة شفافة. هذا ما يجعل التحويل مفيدًا للشعارات والأيقونات.</p>\n<h2 id=\"how-much-smaller\">كم يصغّر WebP عن PNG؟</h2>\n<p>كم يصغّر WebP عن PNG؟ بنسبة 25 إلى 50 بالمئة تقريبًا، حسب نوع الصورة. الرسوم والشعارات توفر أكثر من الصور الفوتوغرافية.</p>\n<p>لشعار PNG بحجم 500 كيلوبايت، قد يصبح WebP بحجم 200 كيلوبايت. التوفير يتراكم عبر موقع كامل.</p>\n<h2 id=\"transparency-preserved\">الشفافية تُحفظ</h2>\n<p>الشفافية تُحفظ: WebP يدعم قناة ألفا مثل PNG تمامًا. المناطق الشفافة تبقى شفافة بعد التحويل دون أي تغيير.</p>\n<p>تحقق من الشفافية بعد التحويل بفتح الصورة على خلفية ملونة. إذا ظهرت الخلفية من خلال الصورة، فالشفافية سليمة.</p>\n<h2 id=\"quality-settings\">إعدادات الجودة التي تعمل</h2>\n<p>إعدادات الجودة التي تعمل: جودة 90 مناسبة للشعارات والأيقونات، و85 للصور الرئيسية. جودة 95 للشعارات المهمة جدًا.</p>\n<p>للرسوم ذات النصوص، استخدم 90 أو أعلى. النص يضبب بسرعة عند الجودة المنخفضة.</p>\n<h2 id=\"icon-sets\">تحويل مجموعات أيقونات كاملة</h2>\n<p>لتحويل مجموعات أيقونات كاملة، ارفع كل الأيقونات وحوّلها بإعدادات موحدة. الأداة تحوّل الدفعة كاملة وتنزّلها كملف ZIP.</p>\n<p>راجع عينة من الأيقونات بعد التحويل. إذا كانت الحواف حادة والشفافية سليمة، فالدفعة ناجحة.</p>\n<h2 id=\"screenshots-with-text\">اللقطات مع النص</h2>\n<p>اللقطات مع النص: استخدم جودة 90 للقطات النصية. النص يحتاج إلى حدة عالية، والجودة المنخفضة تضببه.</p>\n<p>إذا ضبب النص بعد التحويل، فأعد التحويل بجودة أعلى. لا تحوّل من النسخة المحوّلة، بل من PNG الأصلي.</p>\n<h2 id=\"hero-images\">الصور الرئيسية للمواقع الإلكترونية</h2>\n<p>الصور الرئيسية للمواقع الإلكترونية: استخدم WebP للصور الرئيسية لتسريع صفحاتك. الصورة الرئيسية هي أول ما يراه الزائر، وسرعتها مهمة.</p>\n<p>استخدم جودة 85 للصور الرئيسية. الجودة كافية للشاشة الكبيرة، والملف الأصغر يجعل الصفحة أسرع.</p>\n<h2 id=\"metadata-and-colour\">البيانات الوصفية وملفات الألوان</h2>\n<p>البيانات الوصفية وملفات الألوان: التحويل قد يزيل بيانات EXIF، وهذا يحمي خصوصيتك عند النشر. ملفات الألوان تُحفظ عادة.</p>\n<p>إذا تغيرت الألوان بعد التحويل، فتحقق من ملف الألوان في الصورة الأصلية. بعض الصور تستخدم ملفات ألوان خاصة.</p>\n<h2 id=\"when-webp-is-larger\">متى يكون WebP أكبر؟</h2>\n<p>متى يكون WebP أكبر؟ عندما تكون الصورة بسيطة بألوان قليلة، مثل أيقونة صغيرة. PNG يضغطها جيدًا أصلًا.</p>\n<p>في هذه الحالة النادرة، احتفظ بـPNG. قارن الحجمين قبل الاعتماد على WebP لكل صورة.</p>\n<h2 id=\"png-vs-jpg-decision\">من PNG إلى WebP أم من PNG إلى JPG؟</h2>\n<p>من PNG إلى WebP أم من PNG إلى JPG؟ اختر WebP إذا احتجت إلى شفافية أو أصغر حجم للويب، وJPG إذا احتجت إلى توافق كامل.</p>\n<p>إذا كانت الصورة تحتاج إلى شفافية، فWebP هو الخيار الوحيد. وإذا كانت صورة فوتوغرافية للبريد، فJPG أفضل.</p>\n<h2 id=\"checking-quality\">مراجعة الجودة قبل التنزيل</h2>\n<p>مراجعة الجودة قبل التنزيل: قارن النتيجة بالأصل، وتأكد من أن الشفافية سليمة والنص حاد والألوان صحيحة.</p>\n<p>افتح الصورة على خلفية ملونة للتحقق من الشفافية. إذا ظهرت الخلفية من خلال الصورة، فالشفافية سليمة.</p>\n<h2 id=\"common-mistakes\">أخطاء شائعة يجب تجنبها</h2>\n<p>أخطاء شائعة يجب تجنبها: استخدام جودة منخفضة للنصوص، وعدم التحقق من الشفافية بعد التحويل، وحذف الأصول PNG بعد التحويل.</p>\n<p>تجنبها بمراجعة العينة أولًا، والتحقق من الشفافية على خلفية ملونة، والاحتفاظ بالأصول دائمًا.</p>\n<h2 id=\"webp-for-website-logos\">WebP لشعارات المواقع الإلكترونية</h2>\n<p>WebP لشعارات المواقع الإلكترونية: استخدم WebP للشعارات الشفافة على موقعك. الشعار أصغر وأسرع في التحميل، والشفافية سليمة.</p>\n<p>الشعار هو أول ما يراه الزائر. الشعار السريع يترك انطباعًا احترافيًا.</p>\n<h2 id=\"webp-for-app-icons\">WebP لأيقونات التطبيقات</h2>\n<p>WebP لأيقونات التطبيقات: استخدم WebP لأيقونات التطبيقات إذا كان نظامك يدعمها. الأيقونات أصغر وأسرع في التحميل.</p>\n<p>تحقق من دعم نظامك لـWebP قبل التحويل. بعض أنظمة التطبيقات القديمة لا تدعم WebP.</p>\n<h2 id=\"webp-for-blog-images\">WebP لصور المدونات</h2>\n<p>WebP لصور المدونات: حوّل صور مدونتك إلى WebP لتسريع صفحاتك. المدونات السريعة تحتفظ بالقراء وتحسّن ترتيبها في البحث.</p>\n<p>ابدأ بالصور الأكبر أولًا. الصور الكبيرة هي التي تبطئ صفحاتك أكثر من غيرها.</p>\n<h2 id=\"webp-for-ecommerce\">WebP للتجارة الإلكترونية</h2>\n<p>WebP للتجارة الإلكترونية: حوّل صور منتجاتك إلى WebP لتسريع صفحات المنتجات. السرعة تحسّن تجربة التسوق وتزيد المبيعات.</p>\n<p>كل ثانية توفرها من وقت التحميل تزيد احتمال الشراء. WebP استثمار صغير بعائد كبير للمتاجر.</p>\n<h2 id=\"webp-for-social-graphics\">WebP لرسوم وسائل التواصل</h2>\n<p>WebP لرسوم وسائل التواصل: استخدم WebP للرسوم الشفافة على وسائل التواصل إذا كانت المنصة تدعمها. الرسوم أصغر وأسرع في الرفع.</p>\n<p>وللخطوات العملية، استخدم <a href=\"/ar/tahwil-png-ila-webp/\">محول PNG إلى WebP</a>، واقرأ <a href=\"/ar/blog/kayfiyya-tahwil-png-ila-webp/\">كيفية تحويل PNG إلى WebP</a> و<a href=\"/ar/blog/png-vs-webp/\">PNG مقابل WebP</a>، أو حوّل إلى JPG باستخدام <a href=\"/ar/tahwil-png-ila-jpg/\">محول PNG إلى JPG</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل تحويل PNG إلى WebP يحافظ فعلًا على الخلفيات الشفافة؟","answer":"نعم، التحويل يحافظ على الخلفيات الشفافة تمامًا. WebP يدعم قناة ألفا مثل PNG، لذلك تبقى الشفافية سليمة."},{"question":"كم يصغّر WebP عن PNG للصورة نفسها؟","answer":"WebP أصغر من PNG بنسبة 25 إلى 50 بالمئة تقريبًا، حسب نوع الصورة. الرسوم والشعارات توفر أكثر من الصور الفوتوغرافية."},{"question":"ما إعداد الجودة الأفضل لشعارات PNG الشفافة؟","answer":"جودة 90 مناسبة للشعارات الشفافة: الحواف تبقى حادة والشفافية سليمة. للشعارات المهمة استخدم 95."},{"question":"هل يمكنني تحويل مجموعة أيقونات كاملة من PNG إلى WebP دفعة واحدة؟","answer":"نعم، ارفع كل الأيقونات دفعة واحدة وحوّلها بإعدادات موحدة. الأداة تحوّل الدفعة كاملة وتنزّلها كملف ZIP."},{"question":"هل WebP أفضل من PNG للصور الرئيسية للمواقع؟","answer":"نعم، WebP أفضل للصور الرئيسية: أصغر بكثير بالجودة نفسها، ويدعم الشفافية أيضًا. الصفحات الأسرع تحسّن تجربة الزائر."},{"question":"لماذا أصبح ملف WebP المحوّل أكبر من PNG الأصلي؟","answer":"لأن الصورة بسيطة بألوان قليلة، مثل أيقونة صغيرة. PNG يضغطها جيدًا أصلًا، وWebP قد يكون أكبر في هذه الحالة النادرة."}];
